  const yeniTahta = tahta.slice();
  yeniTahta[index] = isaret;
  return yeniTahta;
}

function sonrakiOyuncu(isaret) {
  return isaret === 'X' ? 'O' : 'X';
}

function kazanan(tahta) {
  const kombinasyonlar = [
