    "logic.test.js": "const { test } = require('node:test');
const assert = require('node:assert/strict');
const { baslangicTahtasi, hamleYap, sonrakiOyuncu, kazanan, beraberlikMi } = require('./logic.js');

test('AC1: baslangicTahtasi() 9 elemanlı ve tüm elemanları null olan bir dizi döner', () => {
  const tahta = baslangicTahtasi();
  assert.strictEqual(tahta.length, 9);
  assert.ok(tahta.every((hucre) => hucre === null));
});

test('AC2: Boş bir hücreye hamleYap(tahta, 4, X) çağrıldığında dönen tahtanın 4. indeksi X olur', () => {
  const tahta = baslangicTahtasi();
  const yeniTahta = hamleYap(tahta, 4, 'X');
  assert.notStrictEqual(yeniTahta, false);
  assert.strictEqual(yeniTahta[4], 'X');
});

test('AC3: Dolu bir hücreye hamle yapılmaya çalışıldığında hamleYap() tahtayı değiştirmeden false döner', () => {
  const tahta = baslangicTahtasi();
  const yeniTahta = hamleYap(tahta, 4, 'X');
  const sonuc = hamleYap(yeniTahta, 4, 'O');
  assert.strictEqual(sonuc, false);
  assert.strictEqual(yeniTahta[4], 'X');
});

test('AC4: sonrakiOyuncu(X) O, sonrakiOyuncu(O) X döner', () => {
  assert.strictEqual(sonrakiOyuncu('X'), 'O');
  assert.strictEqual(sonrakiOyuncu('O'), 'X');
});

test('AC5: Aynı işaretten üç tanesi bir satırda yan yana geldiğinde kazanan() o işareti döndürür', () => {
  const tahta = ['X', 'X', 'X', null, null, null, null, null, null];
  assert.strictEqual(kazanan(tahta), 'X');
});

test('AC6: Aynı işaretten üç tanesi bir sütunda yan yana geldiğinde kazanan() o işareti döndürür', () => {
  const tahta = ['O', null, null, 'O', null, null, 'O', null, null];
  assert.strictEqual(kazanan(tahta), 'O');
});

test('AC7: Aynı işaretten üç tanesi çaprazda yan yana geldiğinde kazanan() o işareti döndürür', () => {
  const tahta1 = ['X', null, null, null, 'X', null, null, null, 'X'];
  assert.strictEqual(kazanan(tahta1), 'X');
  const tahta2 = [null, null, 'O', null, 'O', null, 'O', null, null];
  assert.strictEqual(kazanan(tahta2), 'O');
});

