  }
</style>
</head>
<body>
<h1>Tic-Tac-Toe</h1>
<div id="durum">Sıra: X</div>
<canvas id="oyunAlani" width="300" height="300"></canvas>
<button id="yeniOyun">Yeni Oyun</button>

<script src="logic.js"></script>
<script>
(function () {
  const canvas = document.getElementById('oyunAlani');
  const ctx = canvas.getContext('2d');
  const durumEl = document.getElementById('durum');
  const yeniOyunBtn = document.getElementById('yeniOyun');
  const hucreBoyutu = canvas.width / 3;

  let tahta = baslangicTahtasi();
  let siradaki = 'X';
  let oyunBitti = false;

  function ciz() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = '#eee';
    ctx.lineWidth = 2;
    for (let i = 1; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(i * hucreBoyutu, 0);
      ctx.lineTo(i * hucreBoyutu, canvas.height);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, i * hucreBoyutu);
      ctx.lineTo(canvas.width, i * hucreBoyutu);
      ctx.stroke();
    }

    ctx.font = '64px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    for (let index = 0; index < 9; index++) {
      const deger = tahta[index];
      if (deger === null) continue;
      const satir = Math.floor(index / 3);
      const sutun = index % 3;
      const merkezX = sutun * hucreBoyutu + hucreBoyutu / 2;
      const merkezY = satir * hucreBoyutu + hucreBoyutu / 2;
      ctx.fillStyle = deger === 'X' ? '#4da6ff' : '#ff704d';
      ctx.fillText(deger, merkezX, merkezY);
    }
  }

  function durumGuncelle() {
    const kazananIsaret = kazanan(tahta);
    if (kazananIsaret !== null) {
      durumEl.textContent = kazananIsaret + ' kazandı!';
      oyunBitti = true;
    } else if (beraberlikMi(tahta)) {
      durumEl.textContent = 'Berabere!';
      oyunBitti = true;
    } else {
      durumEl.textContent = 'Sıra: ' + siradaki;
      oyunBitti = false;
    }
  }

  canvas.addEventListener('click', function (e) {
    if (oyunBitti) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const sutun = Math.floor(x / hucreBoyutu);
    const satir = Math.floor(y / hucreBoyutu);
    const index = satir * 3 + sutun;

    const sonuc = hamleYap(tahta, index, siradaki);
    if (sonuc === false) return;

    tahta = sonuc;
    durumGuncelle();
    if (!oyunBitti) {
      siradaki = sonrakiOyuncu(siradaki);
    }
    ciz();
  });

  yeniOyunBtn.addEventListener('click', function () {
    tahta = baslangicTahtasi();
    siradaki = 'X';
    oyunBitti = false;
    durumGuncelle();
    ciz();
  });

  durumGuncelle();
  ciz();
})();
</script>
</body>
</html>
